hl.env("XDG_SESSION_TYPE", "wayland")

-- supergfxctl GPU 모드에 따라 VA-API 및 GLX 드라이버를 유동적으로 설정합니다.
-- Integrated(내장) 및 Hybrid(하이브리드) 모드일 때는 내장 그래픽(AMD)을 주 화면 출력/가속으로 사용해야 하므로,
-- Dedicated(외장 전용) 모드일 때만 NVIDIA 관련 환경 변수를 지정해 프리징을 방지합니다.
local handle = io.popen("supergfxctl -g 2>/dev/null")
local gpu_mode = ""
if handle then
    gpu_mode = handle:read("*all"):gsub("%s+", "")
    handle:close()
end

local function resolve_device(path)
    local pipe = io.popen("readlink -f " .. path)
    if pipe then
        local res = pipe:read("*all"):gsub("%s+", "")
        pipe:close()
        if res ~= "" then
            return res
        end
    end
    return path
end

local amd_card = resolve_device("/dev/dri/by-path/pci-0000:65:00.0-card")
local nvidia_card = resolve_device("/dev/dri/by-path/pci-0000:01:00.0-card")

if gpu_mode == "Dedicated" or gpu_mode == "AsusMuxDgpu" then
    hl.env("LIBVA_DRIVER_NAME", "nvidia")
    hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")
    hl.env("AQ_DRM_DEVICES", nvidia_card)
    hl.env("WLR_DRM_DEVICES", nvidia_card)
end

-- Kime 한글 입력기 변수
hl.env("GTK_IM_MODULE", "kime")
hl.env("QT_IM_MODULE", "kime")
hl.env("XMODIFIERS", "@im=kime")

